    /**
     * Custom DML update/insert/delete logic here.
     * @param operation the operation type
     * @param e the transaction event
     */
    protected void doDML(int operation, TransactionEvent e) {

        if (operation == DML_INSERT) {
            System.err.println("DML_INSERT" + this.getUndefineedPenaltyComFlag());
            if (this.getUndefineedPenaltyComFlag().compareToIgnoreCase("Y") == 0) {
                BigDecimal UndefineedPenaltyCom =
                    (BigDecimal) ADFContext.getCurrent().getSessionScope().get("undefinedPenaltyComb");
                this.setUnDefineedPenalty(UndefineedPenaltyCom);
            }

            if (this.getPenaltyAmountComFlag().compareToIgnoreCase("Y") == 0) {


                BigDecimal PenaltyCom =
                    (BigDecimal) ADFContext.getCurrent().getSessionScope().get("PenaltyComb");
this.setPenaltyAmount(PenaltyCom);
            }

            if (this.getWorkAmountComFlag().compareToIgnoreCase("Y") == 0) {


                BigDecimal WorkAmountPenaltyCom =
                    (BigDecimal) ADFContext.getCurrent().getSessionScope().get("workAmountPenaltyComb");
this.setWorkAmount(WorkAmountPenaltyCom);
            }


            Integer flag = 0;
            if (ADFContext.getCurrent().getSessionScope().get("CheckHearingDate") != null)
                flag = (Integer) ADFContext.getCurrent().getSessionScope().get("CheckHearingDate");


            if (flag > 0)

            {
                BigDecimal Iddecision = (BigDecimal) ADFContext.getCurrent().getSessionScope().get("Iddecision");
                this.setDecisionId(Iddecision);
            }
        }

        if (this.getDeleteFlag() != null && this.getDeleteFlag().equalsIgnoreCase("Y")) {
            operation = DML_DELETE;
            System.err.println("Delete");
        }
        super.doDML(operation, e);
    }
